from pwn import *
import itertools

def test_sequence(sequence):
    try:
        p = process('/home/ctfplayer/ctf_files/main')
        p.recvuntil(b'path:')
        p.sendline(sequence.encode())
        output = p.recvall(timeout=1).decode()
        p.close()
        if 'panicked' not in output and 'CAN\'T GO' not in output:
            return True, output
        return False, output
    except:
        return False, "Timeout or Error"

def main():
    moves = ['N', 'O', 'P', 'Q']

    # Test sequences of increasing length
    for length in range(1, 8):
        print(f"\nTesting sequences of length {length}:")
        for seq in itertools.product(moves, repeat=length):
            sequence = ''.join(seq)
            success, output = test_sequence(sequence)
            if success:
                print(f"Found possible valid sequence: {sequence}")
                print(f"Output: {output}")

            # If we find something interesting, try extending it
            if 'flag' in output.lower() or 'win' in output.lower():
                print(f"!!! Potentially found solution: {sequence} !!!")
                print(f"Complete output: {output}")
                return

if __name__ == '__main__':
    main()

