from pwn import *

def try_sequence(sequence):
    p = process('/home/ctfplayer/ctf_files/main')
    p.sendline(sequence.encode())
    try:
        result = p.recvall(timeout=2).decode()
        p.close()
        return result
    except:
        p.close()
        return None

def main():
    # Test all combinations systematically
    moves = 'NOPQ'
    sequences = []

    # Generate all possible 4-character sequences
    for p1 in moves:
        for p2 in moves:
            for p3 in moves:
                for p4 in moves:
                    sequences.append(p1 + p2 + p3 + p4)

    print(f"Testing {len(sequences)} possible sequences...")

    for seq in sequences:
        print(f"\nTrying sequence: {seq}")
        result = try_sequence(seq)
        if result:
            print(f"Output: {result}")
            if "flag" in result.lower() or "win" in result.lower():
                print(f"!!! Potential winning sequence found: {seq} !!!")
                print(result)
                break

if __name__ == '__main__':
    main()

